using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Drawing;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Grasshopper.Kernel;using Rhino;using Rhino.Geometry;
namespace TopoptLab.GH {
 public abstract class FinalJobComponent:Component {
  WorkerJob job;readonly List<WorkerJob> detached=new List<WorkerJob>();bool initialized,lastRun,lastStop,lastReset;
  protected FinalJobComponent(string name,string nickname,string description):base(name,nickname,description,"10 Final Geometry 3D"){}
  protected abstract int RunIndex{get;}protected abstract JObject Request(IGH_DataAccess da,JObject source);
  protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddTextParameter("Result","R","Completed surface or final FEM result",GH_ParamAccess.item);p.AddTextParameter("Status","Status","Worker stage or validation error",GH_ParamAccess.item);p.AddTextParameter("Report","Report","HTML report path",GH_ParamAccess.item);p.AddTextParameter("Files","Files","Surface STL path or FEM job folder",GH_ParamAccess.item);}
  void Schedule(){var doc=OnPingDocument();if(doc!=null)doc.ScheduleSolution(400,d=>{if(OnPingDocument()==d)ExpireSolution(false);});}
  void Detach(){if(job!=null){job.Cancel();detached.Add(job);job=null;}}
  public override void RemovedFromDocument(GH_Document doc){Detach();foreach(var old in detached)old.Cancel();base.RemovedFromDocument(doc);}
  protected override void SolveInstance(IGH_DataAccess da){
   bool run=false,stop=false,reset=false;da.GetData(RunIndex,ref run);da.GetData(RunIndex+1,ref stop);da.GetData(RunIndex+2,ref reset);
   bool start=initialized&&run&&!lastRun,stopEdge=initialized&&stop&&!lastStop,resetEdge=initialized&&reset&&!lastReset;initialized=true;lastRun=run;lastStop=stop;lastReset=reset;
   try{
    foreach(var old in detached.ToArray())if(!old.Running){old.Process.Dispose();detached.Remove(old);}if(resetEdge)Detach();if(stopEdge&&job!=null)job.Cancel();
    string json=null;JObject source=null,request=null;if(da.GetData(0,ref json)&&!string.IsNullOrWhiteSpace(json))source=JObject.Parse(json);
    if(source!=null&&(string)source["status"]=="completed")request=Request(da,source);
    if(request==null){da.SetData(1,"Awaiting completed source result");Message="Awaiting source";if(start)AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,"Complete the preceding stage before Run");return;}
    request["workflow"]="final_geometry";string fingerprint=WorkerJob.Hash(request.ToString(Formatting.None));
    if(start&&!resetEdge&&!stop){if(job!=null&&job.Running)AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,"A job is running; Stop or Reset before restarting");else{Detach();job=WorkerJob.Start(request,fingerprint,Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"local-settings.json"));}}
    string status="Ready - press Run";
    if(job!=null){var data=job.Snapshot();if(job.Fingerprint!=fingerprint)status="Inputs changed; previous result hidden. Reset, then Run.";
     else if(data!=null){status=(string)data["status"];
      if(status=="error"){status+=": "+(string)data["message"];AddRuntimeMessage(GH_RuntimeMessageLevel.Error,status);}
      else if(status=="completed"){da.SetData(0,data.ToString(Formatting.None));da.SetData(2,(string)data["engineering"]["report_file"]);da.SetData(3,(string)data["surface_file"]??job.Folder);
       var limits=data["engineering"]["design_limits"] as JObject;if(limits!=null){status+=" | limits: "+limits["status"];if((string)limits["status"]=="exceeded")AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,"Final FEM design limits exceeded; read Report");var accuracy=data["engineering"]["accuracy"];if(accuracy!=null)status+=" | mesh study: "+accuracy["status"];if((string)data["engineering"]["mesh_quality_status"]=="poor_elements_present")AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,"Poor tetrahedra present; inspect quality and mesh study in Report");}
      }else if(status=="running"){status+=" | "+(string)data["stage"];if(!job.Running){status="Worker stopped unexpectedly; inspect "+job.Folder;AddRuntimeMessage(GH_RuntimeMessageLevel.Error,status);}}
     }else status=job.Running?"Starting external calculation":"Worker exited without result; inspect "+job.Folder;
     if(job.Running&&File.Exists(Path.Combine(job.Folder,"cancel")))status="Stopping calculation...";
    }
    da.SetData(1,status);Message=status;
   }catch(Exception ex){Error(ex);da.SetData(1,ex.Message);Message="Error";}
   finally{if(job!=null&&job.Running||detached.Any(j=>j.Running))Schedule();}
  }
 }
 public sealed class FinalGeometry3DComponent:FinalJobComponent {
  public FinalGeometry3DComponent():base("TopOpt Final Geometry 3D","Final Geometry 3D","Extract a closed density surface preserving protected regions. Optional shelf CAD contract restores nominal plates and clearances. Geometry is not yet reanalysed."){}
  public override Guid ComponentGuid{get{return new Guid("aa5e34bd-1140-4300-9000-000000000001");}}protected override int RunIndex{get{return 5;}}
  protected override void RegisterInputParams(GH_InputParamManager p){p.AddTextParameter("Optimization result","Source","Completed Engineering optimization 3D",GH_ParamAccess.item);p[0].Optional=true;p.AddNumberParameter("Threshold","T","Density isovalue",GH_ParamAccess.item,.4);p.AddNumberParameter("Smoothing","Smooth","Gaussian density smoothing in cells; 0 disables; Keep is reinserted exactly",GH_ParamAccess.item,.5);p.AddTextParameter("Print review","Print","Optional Print Review settings",GH_ParamAccess.item);p[3].Optional=true;p.AddMeshParameter("Edited mesh","Edited","Optional closed triangulatable mesh in world coordinates; checked against original Keep/envelope",GH_ParamAccess.item);p[4].Optional=true;p.AddBooleanParameter("Run","Run","Extract or validate edited mesh",GH_ParamAccess.item,false);p.AddBooleanParameter("Stop","Stop","Cancel",GH_ParamAccess.item,false);p.AddBooleanParameter("Reset","Reset","Cancel and clear",GH_ParamAccess.item,false);p.AddTextParameter("Nominal CAD specification","CAD","Optional Shelf Bracket specification. Restores nominal plates/holes to chord tolerance; requires matching CAD loads.",GH_ParamAccess.item);p[8].Optional=true;p.AddTextParameter("Nominal CAD loads","CAD loads","Matching Bracket Cases Summary. Total loads are reapplied to nominal physical regions.",GH_ParamAccess.item);p[9].Optional=true;p.AddNumberParameter("CAD chord tolerance mm","CAD tolerance","Maximum radial chord error for nominal circular holes in exported triangle surface",GH_ParamAccess.item,.05);p.AddNumberParameter("Envelope cleanup mm","Cleanup","Shelf CAD only: snap surface vertices to nominal envelope planes within this distance per axis; 0 disables. Actual movement is reported.",GH_ParamAccess.item,0);p.AddNumberParameter("Web cleanup mm","Web cleanup","Shelf CAD only: bounded simplification of the extracted web before nominal plates/holes are restored; 0 disables. Exported geometry records the cleanup.",GH_ParamAccess.item,.01);}
  protected override JObject Request(IGH_DataAccess da,JObject source){double t=.4,s=.5;string print=null;Mesh edited=null;da.GetData(1,ref t);da.GetData(2,ref s);da.GetData(3,ref print);da.GetData(4,ref edited);
   if(!CadGeometry.Finite(t)||t<.05||t>.95||!CadGeometry.Finite(s)||s<0||s>2)throw new ArgumentException("Threshold .05..95; smoothing 0..2 cells");
   var request=new JObject{{"action","extract"},{"source_result",source},{"settings",new JObject{{"threshold",t},{"smoothing",s}}}};
   if(!string.IsNullOrWhiteSpace(print))request["manufacturing_review"]=JObject.Parse(print);
    string cad=null,loads=null;double chord=.05,cleanup=0,webCleanup=.01;da.GetData(8,ref cad);da.GetData(9,ref loads);da.GetData(10,ref chord);da.GetData(11,ref cleanup);da.GetData(12,ref webCleanup);
    if(!string.IsNullOrWhiteSpace(cad)||!string.IsNullOrWhiteSpace(loads)){if(string.IsNullOrWhiteSpace(cad)||string.IsNullOrWhiteSpace(loads)||!CadGeometry.Finite(chord)||chord<=0||!CadGeometry.Finite(cleanup)||cleanup<0||!CadGeometry.Finite(webCleanup)||webCleanup<0)throw new ArgumentException("Connect matching CAD specification and CAD loads, with positive chord tolerance and nonnegative cleanup distance");request["settings"]["cad_interfaces"]=new JObject{{"specification",JObject.Parse(cad)},{"loading",JObject.Parse(loads)},{"chord_tolerance_mm",chord},{"envelope_snap_mm",cleanup},{"web_cleanup_mm",webCleanup}};}
   if(edited!=null){var m=edited.DuplicateMesh();m.Faces.ConvertQuadsToTriangles();m.Vertices.CombineIdentical(true,true);m.Compact();if(!m.IsValid||!m.IsClosed)throw new ArgumentException("Edited mesh must be valid and closed");request["edited_mesh"]=new JObject{{"nodes",new JArray(m.Vertices.Select(v=>new JArray((double)v.X,(double)v.Y,(double)v.Z)))},{"triangles",new JArray(m.Faces.Select(f=>new JArray(f.A,f.B,f.C)))}};}
   return request;
  }
 }
 public sealed class FinalFem3DComponent:FinalJobComponent {
  public FinalFem3DComponent():base("TopOpt Final FEM 3D","Final FEM 3D","Remesh an extracted surface with Gmsh and solve independent load cases using TET4. Optional three-level mesh study. Surface support patches required."){}
  public override Guid ComponentGuid{get{return new Guid("aa5e34bd-1140-4300-9000-000000000002");}}protected override int RunIndex{get{return 6;}}
  protected override void RegisterInputParams(GH_InputParamManager p){p.AddTextParameter("Final geometry","Source","Completed Final Geometry result",GH_ParamAccess.item);p[0].Optional=true;p.AddNumberParameter("Mesh size","h","Independent tetrahedral mesh target size; 0 uses original voxel size",GH_ParamAccess.item,0);p.AddTextParameter("Engineering settings","Settings","Backend/thread settings; optional",GH_ParamAccess.item);p[2].Optional=true;p.AddIntegerParameter("Mesh levels","Levels","1 FEM only; 2/3 refinement levels, each size x0.75",GH_ParamAccess.item,1);p.AddNumberParameter("Accuracy tolerance","Tolerance","Relative change across mesh levels; .05=5%",GH_ParamAccess.item,.05);p.AddTextParameter("Design limits","Limits","Optional new checking limits; otherwise use source project limits",GH_ParamAccess.item);p[5].Optional=true;p.AddBooleanParameter("Run","Run","Start remesh and FEM",GH_ParamAccess.item,false);p.AddBooleanParameter("Stop","Stop","Cancel mesher or iterative solve",GH_ParamAccess.item,false);p.AddBooleanParameter("Reset","Reset","Cancel and clear",GH_ParamAccess.item,false);}
  protected override JObject Request(IGH_DataAccess da,JObject source){double h=0,t=.05;int levels=1;string settings=null,limits=null;da.GetData(1,ref h);da.GetData(2,ref settings);da.GetData(3,ref levels);da.GetData(4,ref t);da.GetData(5,ref limits);
   if((string)source["mode"]!="surface")throw new ArgumentException("Connect Final Geometry surface result");
   if(!CadGeometry.Finite(h)||h<0||levels<1||levels>3||!CadGeometry.Finite(t)||t<.001||t>.2)throw new ArgumentException("Mesh size >=0; levels 1..3; tolerance .001..0.2");
   var cfg=string.IsNullOrWhiteSpace(settings)?new JObject{{"backend","cpu-cg"},{"threads",4}}:(JObject)JObject.Parse(settings)["settings"];
   cfg["mesh_size"]=h>0?h:(double)source["source_project"]["domain"]["cell"];cfg["levels"]=levels;cfg["accuracy_tolerance"]=t;
   var request=new JObject{{"action","analyze"},{"source_result",source},{"settings",cfg}};if(!string.IsNullOrWhiteSpace(limits))request["design_limits"]=JObject.Parse(limits);return request;
  }
 }
 public sealed class PrintReviewComponent:Component {
  public PrintReviewComponent():base("TopOpt Print Review","Print Review","Additive geometry screening: build direction, overhangs and sampled normal-ray thickness. Does not enforce printability in optimization.","10 Final Geometry 3D"){}
  public override Guid ComponentGuid{get{return new Guid("aa5e34bd-1140-4300-9000-000000000003");}}
  protected override void RegisterInputParams(GH_InputParamManager p){p.AddVectorParameter("Build direction","Build","World build direction, from plate upward",GH_ParamAccess.item,Vector3d.ZAxis);p.AddNumberParameter("Overhang angle","Angle","Maximum wall overhang from vertical, degrees",GH_ParamAccess.item,45);p.AddNumberParameter("Minimum wall","Wall","Model length units, sampled normal-ray check; 0 disables limit",GH_ParamAccess.item,0);p.AddBooleanParameter("Enabled","On","Enable geometric print review",GH_ParamAccess.item,true);}
  protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddTextParameter("Print review","Print","Connect to Final Geometry",GH_ParamAccess.item);p.AddTextParameter("Info","Info","Scope of checks",GH_ParamAccess.item);}
  protected override void SolveInstance(IGH_DataAccess da){Vector3d axis=Vector3d.ZAxis;double angle=45,wall=0;bool on=true;if(!da.GetData(0,ref axis)||!da.GetData(1,ref angle)||!da.GetData(2,ref wall)||!da.GetData(3,ref on))return;try{if(!axis.IsValid||!axis.Unitize()||!CadGeometry.Finite(angle)||angle<1||angle>89||!CadGeometry.Finite(wall)||wall<0)throw new ArgumentException("Use a nonzero direction, angle 1..89 and nonnegative wall size");da.SetData(0,new JObject{{"enabled",on},{"build_direction",new JArray(axis.X,axis.Y,axis.Z)},{"overhang_angle",angle},{"minimum_wall",wall},{"samples",500}}.ToString());da.SetData(1,"Orange: overhang above angle. Red: sampled wall below limit. Bed-contact faces excluded from overhang. Normal thickness is sampled, not a guaranteed global minimum. Material anisotropy, toolpaths and support removal are not checked.");Message=on?"Additive geometry screen":"Off";}catch(Exception e){Error(e);}}
 }
 public sealed class FinalResults3DComponent:Component,IResultLegend {
  Mesh preview;ResultLegend legend;bool show=true,lastBake,initialized;string geometryInfo;
  public FinalResults3DComponent():base("TopOpt Final Results 3D","Final Results 3D","Extracted surface or final TET4 FEM, with print flags, case response and explicit Bake/Undo.","10 Final Geometry 3D"){}
  public override Guid ComponentGuid{get{return new Guid("aa5e34bd-1140-4300-9000-000000000004");}}
  public bool LegendVisible{get{return show&&preview!=null&&legend!=null;}}
  public override BoundingBox ClippingBox{get{return preview==null?BoundingBox.Empty:preview.GetBoundingBox(false);}}
  public override void ClearData(){preview=null;legend=null;geometryInfo=null;base.ClearData();}
  public override void DrawViewportMeshes(IGH_PreviewArgs args){if(show&&preview!=null)args.Display.DrawMeshFalseColors(preview);}
  public override void DrawViewportWires(IGH_PreviewArgs args){if(LegendVisible)legend.Draw(args,this);else if(show&&preview!=null&&geometryInfo!=null)args.Display.Draw2dText(geometryInfo,Color.DarkSlateGray,new Point2d(20,35),false,13);}
  protected override void RegisterInputParams(GH_InputParamManager p){p.AddTextParameter("Result","R","Final Geometry / Final FEM (optionally selected through Case Result)",GH_ParamAccess.item);p.AddIntegerParameter("Field","Field","FEM: 0 or 2 stress, 1 displacement. Geometry: print flags",GH_ParamAccess.item,0);p.AddNumberParameter("Deformation scale","Scale","Display only",GH_ParamAccess.item,0);p.AddNumberParameter("Legend maximum","Max","0 automatic; positive fixed FEM range",GH_ParamAccess.item,0);p.AddBooleanParameter("Show preview","Preview","Preview visibility",GH_ParamAccess.item,true);p.AddBooleanParameter("Bake","Bake","Button pulse: bake undeformed mesh with provenance and Undo",GH_ParamAccess.item,false);}
  protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddMeshParameter("Mesh","Mesh","Undeformed surface",GH_ParamAccess.item);p.AddTextParameter("Info","Info","Geometry, FEM and manufacturing status",GH_ParamAccess.item);}
  static Color Ramp(double x){x=Math.Max(0,Math.Min(1,x));return x<.5?Color.FromArgb((int)(510*x),(int)(510*x),200):Color.FromArgb(255,(int)(510*(1-x)),(int)(400*(1-x)));}
  protected override void SolveInstance(IGH_DataAccess da){preview=null;legend=null;geometryInfo=null;bool bake=false;da.GetData(5,ref bake);bool edge=initialized&&bake&&!lastBake;initialized=true;lastBake=bake;string json=null;int field=0;double scale=0,max=0;if(!da.GetData(0,ref json))return;da.GetData(1,ref field);da.GetData(2,ref scale);da.GetData(3,ref max);da.GetData(4,ref show);try{
   if(field<0||field>2||!CadGeometry.Finite(scale)||scale<0||!CadGeometry.Finite(max)||max<0)throw new ArgumentException("Invalid field, scale or maximum");var d=JObject.Parse(json);if((string)d["schema"]!="topoptlab-gh-surface-result-v1"||(string)d["status"]!="completed")throw new ArgumentException("Connect a completed Final Geometry or Final FEM result");bool fem=(string)d["mode"]=="final_fem";
   var nodes=((JArray)d["nodes"]).Select(p=>new Point3d((double)p[0],(double)p[1],(double)p[2])).ToArray();var tris=d["triangles"].ToObject<int[][]>();var u=fem?((JArray)d["displacement"]).Select(p=>new Vector3d((double)p[0],(double)p[1],(double)p[2])).ToArray():new Vector3d[nodes.Length];var vm=fem?d["von_mises"].ToObject<double[]>():null;var owners=fem?d["boundary_owners"].ToObject<int[]>():null;
   var manufacturing=d["manufacturing_review"] as JObject;var over=manufacturing!=null&&manufacturing["overhang_faces"]!=null?new HashSet<int>(manufacturing["overhang_faces"].Values<int>()):new HashSet<int>();var thin=manufacturing!=null&&manufacturing["thin_sample_faces"]!=null?new HashSet<int>(manufacturing["thin_sample_faces"].Values<int>()):new HashSet<int>();double actual=fem?(field==1?u.Max(v=>v.Length):vm.Max()):0,maximum=max>0?max:actual;
   var undeformed=new Mesh();foreach(var p in nodes)undeformed.Vertices.Add(p);foreach(var f in tris)undeformed.Faces.AddFace(f[0],f[1],f[2]);undeformed.Normals.ComputeNormals();preview=new Mesh();
   for(int e=0;e<tris.Length;e++){int start=preview.Vertices.Count;foreach(int n in tris[e]){preview.Vertices.Add(nodes[n]+scale*u[n]);double value=fem?(field==1?u[n].Length:vm[owners[e]]):0;preview.VertexColors.Add(fem?Ramp(maximum>0?value/maximum:0):thin.Contains(e)?Color.Firebrick:over.Contains(e)?Color.DarkOrange:Color.LightSlateGray);}preview.Faces.AddFace(start,start+1,start+2);}preview.Normals.ComputeNormals();
   string info=fem?"FINAL TET4 FEM. Constant element stress. Mesh study: "+d["engineering"]["accuracy"]["status"]+EngineeringInfo.Summary(d):"EXTRACTED GEOMETRY — NOT REANALYSED. Closed: "+d["geometry"]["closed"]+"; material components: "+d["geometry"]["solid_components"]+". Print screen: "+(manufacturing==null?"not requested":(string)manufacturing["status"])+". Orange=overhang; red=sampled thin wall.\nSampled normal thickness: "+(manufacturing==null?null:manufacturing["sampled_wall_minimum"])+". Export: "+d["surface_file"];
   if(fem){legend=ResultLegend.Create(d,field==1?"Displacement":"TET4 von Mises",field==1?"displacement":"stress",maximum,actual,scale,Ramp);legend.Title="FINAL TETRAHEDRAL FEM";}else geometryInfo="EXTRACTED GEOMETRY / not reanalysed | orange: overhang | red: sampled thin wall";
   da.SetData(0,undeformed);da.SetData(1,info);Message=fem?"Final TET4 FEM":"Surface / print review";
   if(edge){if(!undeformed.IsValid||!undeformed.IsClosed)throw new ArgumentException("Bake requires a valid closed mesh");var doc=RhinoDoc.ActiveDoc;if(doc==null)throw new ArgumentException("Open a Rhino document");uint undo=doc.BeginUndoRecord("Bake TopOptLab final geometry");try{var attr=new Rhino.DocObjects.ObjectAttributes{Name=fem?"TopOptLab final FEM mesh":"TopOptLab extracted surface"};attr.SetUserString("analysis",fem?"Conforming TET4 FEM; inspect report limits":"Geometry only; not reanalysed");attr.SetUserString("geometry_hash",(string)d["geometry_hash"]);attr.SetUserString("report",(string)d["engineering"]["report_file"]);if(doc.Objects.AddMesh(undeformed,attr)==Guid.Empty)throw new InvalidOperationException("Rhino could not add the final mesh");doc.Views.Redraw();}finally{doc.EndUndoRecord(undo);}}
  }catch(Exception ex){Error(ex);}}
 }
